// Package sqlc mirrors code generated by sqlc, whose queries go through a
// DBTX interface instead of a database/sql or pgx type.
package sqlc

import (
	"context"
	"database/sql"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

type DBTX interface {
	ExecContext(context.Context, string, ...interface{}) (sql.Result, error)
	PrepareContext(context.Context, string) (*sql.Stmt, error)
	QueryContext(context.Context, string, ...interface{}) (*sql.Rows, error)
	QueryRowContext(context.Context, string, ...interface{}) *sql.Row
}

type Queries struct {
	db DBTX
}

const getUser = `-- name: GetUser :one
SELECT id, name FROM users
WHERE id = $1 LIMIT 1
`

func (q *Queries) GetUser(ctx context.Context, id int64) {
	q.db.QueryRowContext(ctx, getUser, id)
}

const brokenQuery = `-- name: Broken :many
SELECT id FROM users WHERE
`

func (q *Queries) Broken(ctx context.Context) {
	q.db.QueryContext(ctx, brokenQuery) // want `\[invalid-sql\] invalid SQL syntax: syntax error at end of input`
}

type PgxDBTX interface {
	Exec(context.Context, string, ...interface{}) (pgconn.CommandTag, error)
	Query(context.Context, string, ...interface{}) (pgx.Rows, error)
	QueryRow(context.Context, string, ...interface{}) pgx.Row
}

func pgxStyle(ctx context.Context, db PgxDBTX, ids []int64) {
	for _, id := range ids {
		db.QueryRow(ctx, "SELECT name FROM users WHERE id = $1", id) // want `\[n-plus-one\]`
	}
}

type Legacy interface {
	Query(string, ...interface{}) (*sql.Rows, error)
}

func legacy(db Legacy) {
	db.Query("SELECT 1") // want `\[missing-context\] Query\(\) called without context`
}
